<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\unit\Features\OAuth\Client\Domain;

use Civi\Lughauth\Features\OAuth\Client\Domain\DcrMetadataPolicy;
use Civi\Lughauth\Features\OAuth\Client\Domain\DcrRegistrationRules;
use Civi\Lughauth\Features\OAuth\Client\Domain\DynamicClientRequest;
use Civi\Lughauth\Features\OAuth\Client\Domain\Exception\DynamicClientException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

final class DcrMetadataPolicyUnitTest extends TestCase
{
    /**
     * @return iterable<string, array{DynamicClientRequest, ?string}>
     */
    public static function requests(): iterable
    {
        $cb = ['https://app.example.com/cb'];
        yield 'default request' => [new DynamicClientRequest($cb), null];
        yield 'code and refresh' => [new DynamicClientRequest($cb, grantTypes: ['authorization_code', 'refresh_token']), null];
        yield 'public client' => [new DynamicClientRequest($cb, tokenEndpointAuthMethod: 'none'), null];
        yield 'grant out of the rules' => [new DynamicClientRequest($cb, grantTypes: ['authorization_code', 'client_credentials']), 'invalid_client_metadata'];
        yield 'password without permission' => [new DynamicClientRequest($cb, grantTypes: ['password'], responseTypes: []), 'invalid_client_metadata'];
        yield 'no grant types' => [new DynamicClientRequest($cb, grantTypes: []), 'invalid_client_metadata'];
        yield 'non string grant' => [new DynamicClientRequest($cb, grantTypes: [['authorization_code']]), 'invalid_client_metadata'];
        yield 'implicit response type without grant' => [new DynamicClientRequest($cb, responseTypes: ['code id_token']), 'invalid_client_metadata'];
        yield 'unknown response type' => [new DynamicClientRequest($cb, responseTypes: ['magic']), 'invalid_client_metadata'];
        yield 'code without authorization_code' => [new DynamicClientRequest($cb, grantTypes: ['refresh_token']), 'invalid_client_metadata'];
        yield 'auth method not allowed by tenant' => [new DynamicClientRequest($cb, tokenEndpointAuthMethod: 'client_secret_post'), 'invalid_client_metadata'];
        yield 'auth method not supported' => [new DynamicClientRequest($cb, tokenEndpointAuthMethod: 'private_key_jwt'), 'invalid_client_metadata'];
        yield 'script redirect' => [new DynamicClientRequest(['javascript:alert(1)']), 'invalid_redirect_uri'];
        yield 'relative redirect' => [new DynamicClientRequest(['/cb']), 'invalid_redirect_uri'];
    }

    #[DataProvider('requests')]
    public function testRequestIsCheckedAgainstTheTenantRules(DynamicClientRequest $request, ?string $error): void
    {
        $rules = new DcrRegistrationRules(
            DcrRegistrationRules::OPEN,
            ['authorization_code', 'refresh_token', 'password'],
            ['client_secret_basic', 'private_key_jwt', 'none'],
        );

        self::assertSame($error, $this->errorOf($request, $rules));
    }

    public function testPasswordNeedsTheExplicitTenantPermission(): void
    {
        $request = new DynamicClientRequest(['https://app.example.com/cb'], grantTypes: ['password'], responseTypes: []);
        $allowed = new DcrRegistrationRules(DcrRegistrationRules::OPEN, ['password'], ['client_secret_basic'], allowPasswordGrant: true);
        $notListed = new DcrRegistrationRules(DcrRegistrationRules::OPEN, ['authorization_code'], ['client_secret_basic'], allowPasswordGrant: true);

        self::assertNull($this->errorOf($request, $allowed));
        self::assertSame('invalid_client_metadata', $this->errorOf($request, $notListed));
    }

    public function testPublicClientCannotUseConfidentialGrants(): void
    {
        $rules = new DcrRegistrationRules(DcrRegistrationRules::OPEN, ['client_credentials'], ['none']);
        $request = new DynamicClientRequest(['https://app.example.com/cb'], grantTypes: ['client_credentials'], responseTypes: [], tokenEndpointAuthMethod: 'none');

        self::assertSame('invalid_client_metadata', $this->errorOf($request, $rules));
    }

    /**
     * Implicit is retired (EP-08): its response types are rejected even with the implicit grant,
     * which the hybrid ones still need.
     */
    public function testOnlySupportedResponseTypesCanBeRegistered(): void
    {
        $rules = new DcrRegistrationRules(DcrRegistrationRules::OPEN, ['authorization_code', 'implicit'], ['client_secret_basic']);
        $request = static fn (string $responseType): DynamicClientRequest => new DynamicClientRequest(
            ['https://app.example.com/cb'],
            grantTypes: ['authorization_code', 'implicit'],
            responseTypes: [$responseType],
        );

        self::assertNull($this->errorOf($request('id_token code'), $rules));
        self::assertNull($this->errorOf($request('code id_token token'), $rules));
        self::assertSame('invalid_client_metadata', $this->errorOf($request('id_token'), $rules));
        self::assertSame('invalid_client_metadata', $this->errorOf($request('id_token token'), $rules));
        self::assertSame('invalid_client_metadata', $this->errorOf($request('none'), $rules));
    }

    private function errorOf(DynamicClientRequest $request, DcrRegistrationRules $rules): ?string
    {
        try {
            (new DcrMetadataPolicy())->validate($request, $rules);
            return null;
        } catch (DynamicClientException $ex) {
            return $ex->error();
        }
    }
}
